# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GENEL TERİM UYGULAMALARI VE İNDİRGEMELİ DİZİLER</text>\n  <!-- Sol: Genel Terim Analizi -->\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">GENEL TERİM (a_n) İNCELEMELERİ</text>\n  <text x="38" y="90" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. Tam Sayı Terimler:</text>\n  <text x="48" y="108" font-size="11.5" fill="#1d4ed8">a_n = (2n + 18)/n = 2 + 18/n ise n ∈ ℤ⁺ sayısı</text>\n  <text x="48" y="124" font-size="11.5" fill="#1d4ed8">18\'in pozitif bölenleri (1, 2, 3, 6, 9, 18) olur.</text>\n  <text x="38" y="150" font-size="11.5" font-weight="bold" fill="#1e3a8a">2. İşaret İncelemesi (a_n &lt; 0):</text>\n  <text x="48" y="168" font-size="11.5" fill="#1d4ed8">Eşitsizlik tablosu kurulur, yalnız n ∈ ℤ⁺ alınır.</text>\n  <text x="38" y="194" font-size="11.5" font-weight="bold" fill="#1e3a8a">3. En Küçük / En Büyük Terim:</text>\n  <text x="48" y="212" font-size="11.5" fill="#1d4ed8">a_n = a·n² + b·n + c için r = -b/(2a) değerine</text>\n  <text x="48" y="228" font-size="11.5" fill="#1d4ed8">en yakın pozitif tam sayı n yerine yazılır.</text>\n  <!-- Sag: Indirgemeli Diziler -->\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">İNDİRGEME BAĞINTISI ÇÖZÜMÜ</text>\n  <rect x="378" y="78" width="280" height="40" rx="6" fill="#fde68a" stroke="#f59e0b"/>\n  <text x="518" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">Örnek: a₁ = 4 ve a_(n+1) - a_n = 5</text>\n  <text x="518" y="112" text-anchor="middle" font-size="11" fill="#92400e">a₁₀ terimini taraf tarafa toplayarak bulalım:</text>\n  <text x="390" y="138" font-size="11.5" fill="#78350f">n = 1 için:   a₂ - a₁ = 5</text>\n  <text x="390" y="156" font-size="11.5" fill="#78350f">n = 2 için:   a₃ - a₂ = 5</text>\n  <text x="390" y="172" font-size="11.5" fill="#78350f">   ⋮                ⋮</text>\n  <text x="390" y="188" font-size="11.5" fill="#78350f">n = 9 için: + a₁₀ - a₉ = 5  (9 tane 5 toplanır)</text>\n  <line x1="385" y1="196" x2="650" y2="196" stroke="#b45309" stroke-width="1.5"/>\n  <text x="518" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">a₁₀ - a₁ = 9 · 5 = 45  ⇒  a₁₀ = 4 + 45 = 49</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ARİTMETİK DİZİ: ORTAK FARK (d) VE GENEL TERİM (a_n)</text>\n  <!-- Ust: Dizi Zinciri -->\n  <rect x="25" y="42" width="650" height="62" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="90" y="78" text-anchor="middle" font-size="14" font-weight="bold" fill="#166534">a₁</text>\n  <text x="155" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">+d →</text>\n  <text x="220" y="78" text-anchor="middle" font-size="14" font-weight="bold" fill="#166534">a₂ = a₁ + d</text>\n  <text x="305" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">+d →</text>\n  <text x="385" y="78" text-anchor="middle" font-size="14" font-weight="bold" fill="#166534">a₃ = a₁ + 2d</text>\n  <text x="475" y="75" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">... →</text>\n  <text x="580" y="78" text-anchor="middle" font-size="14" font-weight="bold" fill="#14532d">a_n = a₁ + (n - 1)d</text>\n  <!-- Sol Alt: Temel Formuller -->\n  <rect x="25" y="116" width="315" height="128" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="138" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">TEMEL BAĞINTILAR</text>\n  <text x="42" y="164" font-size="12" font-weight="bold" fill="#581c87">• Ortak Fark:  d = a_(n+1) - a_n</text>\n  <text x="42" y="188" font-size="12" font-weight="bold" fill="#581c87">• Genel Terim: a_n = a₁ + (n - 1)·d</text>\n  <text x="42" y="212" font-size="12" font-weight="bold" fill="#581c87">• İki Terim İlişkisi: a_n = a_p + (n - p)·d</text>\n  <text x="42" y="234" font-size="11.5" fill="#6b21a8">• Ortak Fark Oranı: d = (a_n - a_p) / (n - p)</text>\n  <!-- Sag Alt: Terim Yerlestirme -->\n  <rect x="360" y="116" width="315" height="128" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="138" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">TERİM YERLEŞTİRME VE DOĞRUSALLIK</text>\n  <text x="376" y="164" font-size="11.5" fill="#7c2d12">• x ile y arasına k tane terim yerleştirilirse:</text>\n  <text x="386" y="184" font-size="12" font-weight="bold" fill="#c2410c">Terim sayısı = k + 2   ve   d = (y - x) / (k + 1)</text>\n  <text x="376" y="210" font-size="11.5" fill="#7c2d12">• a_n = A·n + B doğrusal dizisinde n\'nin</text>\n  <text x="386" y="228" font-size="11.5" font-weight="bold" fill="#9a3412">katsayısı olan A sayısı doğrudan ortak farktır (d = A).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ARİTMETİK DİZİNİN ÖZELLİKLERİ VE İLK n TERİM TOPLAMI (S_n)</text>\n  <!-- Sol: Ozellikler -->\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">ORTA TERİM VE İNDİS ÖZELLİĞİ</text>\n  <rect x="42" y="78" width="280" height="46" rx="6" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="182" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">a_n = (a_(n-k) + a_(n+k)) / 2</text>\n  <text x="182" y="115" text-anchor="middle" font-size="11" fill="#1d4ed8">Örnek: a₇ = (a₄ + a₁₀) / 2  ⇒  a₄ + a₁₀ = 2·a₇</text>\n  <rect x="42" y="134" width="280" height="46" rx="6" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="182" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">k + m = p + r  ⇒  a_k + a_m = a_p + a_r</text>\n  <text x="182" y="171" text-anchor="middle" font-size="11" fill="#1d4ed8">Örnek: a₂ + a₁₅ = a₆ + a₁₁ = a₁ + a₁₆</text>\n  <text x="182" y="204" text-anchor="middle" font-size="11.5" fill="#1e3a8a">Baştan ve sondan eşit uzaklıktaki</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">terimlerin toplamı birbirine eşittir.</text>\n  <!-- Sag: Ilk n Terim Toplami -->\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">İLK n TERİM TOPLAMI (S_n)</text>\n  <rect x="378" y="78" width="280" height="42" rx="6" fill="#fee2e2" stroke="#ef4444"/>\n  <text x="518" y="104" text-anchor="middle" font-size="13" font-weight="bold" fill="#7f1d1d">S_n = (n / 2) · (a₁ + a_n)</text>\n  <rect x="378" y="128" width="280" height="42" rx="6" fill="#fee2e2" stroke="#ef4444"/>\n  <text x="518" y="154" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7f1d1d">S_n = (n / 2) · [2a₁ + (n - 1)·d]</text>\n  <rect x="378" y="178" width="280" height="52" rx="6" fill="#ffffff" stroke="#dc2626"/>\n  <text x="518" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Toplamdan Terim Bulma:</text>\n  <text x="518" y="218" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">a_n = S_n - S_(n-1)    (ve a₁ = S₁)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
